#include <bits/stdc++.h>
using namespace std;using B=bitset<512>;using F=long double;
struct Din{struct E{int v,rev;F c;};vector<vector<E>>g;vector<int>l,it;Din(int n):g(n),l(n),it(n){} void add(int u,int v,F c){E a{v,(int)g[v].size(),c},b{u,(int)g[u].size(),0};g[u].push_back(a);g[v].push_back(b);}F dfs(int u,int t,F f){if(u==t)return f;for(int&i=it[u];i<(int)g[u].size();i++){E&e=g[u][i];if(e.c>1e-17L&&l[e.v]==l[u]+1){F z=dfs(e.v,t,min(f,e.c));if(z>1e-17L){e.c-=z;g[e.v][e.rev].c+=z;return z;}}}return 0;}void run(int s,int t){while(1){fill(l.begin(),l.end(),-1);queue<int>q;q.push(s);l[s]=0;while(!q.empty()){int u=q.front();q.pop();for(auto&e:g[u])if(e.c>1e-17L&&l[e.v]<0)l[e.v]=l[u]+1,q.push(e.v);}if(l[t]<0)return;fill(it.begin(),it.end(),0);while(dfs(s,t,1e9L)>1e-17L){}}}vector<char> side(int s){vector<char>x(g.size());queue<int>q;q.push(s);x[s]=1;while(!q.empty()){int u=q.front();q.pop();for(auto&e:g[u])if(e.c>1e-14L&&!x[e.v])x[e.v]=1,q.push(e.v);}return x;}};
struct N{bool fixed;B s;int d;};int main(int argc,char**argv){ifstream in(argv[1]);int nf,nn,nr;in>>nf>>nn>>nr;vector<B>fs(nf);vector<int>ds(nf);for(int f=0;f<nf;f++){int n,x;in>>n;ds[f]=round(log2(n));while(n--){in>>x;fs[f][x]=1;}}vector<N>a(nn);vector<pair<int,int>>edges;vector<int>last(nr,-1);for(int i=0;i<nn;i++){int fixed,f,k;in>>fixed>>f>>k;a[i]={bool(fixed),fs[f],ds[f]};while(k--){int r;in>>r;if(last[r]>=0)edges.push_back({last[r],i});last[r]=i;}}vector<B>hy(512);for(int v=1;v<512;v++)for(int x=0;x<512;x++)if(!(__builtin_popcount(v&x)%2))hy[v][x]=1;F pc[11]={};for(int d=1;d<11;d++)pc[d]=powl(d,1-.0015945L);ofstream out(argv[2]);out<<"{\"passes\":[";bool first=true;for(int round=0;round<6;round++){F best=-1e-12L;int bv=0,bl=0;vector<int>bn;long long tested=0;vector<vector<char>>act(512,vector<char>(nn)),los=act;for(int v=1;v<512;v++)for(int i=0;i<nn;i++){act[v][i]=(a[i].s&~hy[v]).any();los[v][i]=a[i].s[v];}for(int v=1;v<512;v++)for(int lam=1;lam<512;lam++){if(!(__builtin_popcount(v&lam)%2))continue;tested++;auto &active=act[lam];auto &loss=los[v];Din G(nn+2);int S=nn,T=nn+1;for(int i=0;i<nn;i++)if(active[i]&&a[i].fixed)G.add(i,T,1e6L);for(auto[u,w]:edges){int r=a[w].d-a[u].d;assert(r>=0);if(active[u]&&active[w]){G.add(w,u,1e6L);if(!loss[w])G.add(u,w,1e6L);}else assert(!active[u]);if(loss[u]&&loss[w])G.add(u,w,pc[r+1]-pc[r]);else if(loss[w]){assert(r>=1);G.add(S,w,pc[r]-pc[r-1]);}else assert(!loss[u]);}G.run(S,T);auto x=G.side(S);F delta=0;vector<int>ns;for(int i=0;i<nn;i++)if(x[i]&&active[i]){assert(!a[i].fixed);ns.push_back(i);}for(auto[u,w]:edges){int r=a[w].d-a[u].d;int z=r-(int)(x[w]&&loss[w])+(int)(x[u]&&loss[u]);assert(z>=0);delta+=pc[z]-pc[r];}if(delta<best){best=delta;bv=v;bl=lam;bn=ns;}}cerr<<"round "<<round<<" delta "<<setprecision(20)<<best<<" n "<<bn.size()<<" v "<<bv<<" lambda "<<bl<<" directions "<<tested<<endl;if(bn.empty())break;if(!first)out<<",";first=false;out<<"{\"kernel\":"<<bv<<",\"lambda\":"<<bl<<",\"nodes\":[";for(int k=0;k<(int)bn.size();k++){int i=bn[k];if(k)out<<",";out<<i;B im;for(int j=0;j<512;j++)if(a[i].s[j])im[j^((__builtin_popcount(j&bl)%2)?bv:0)]=1;a[i].s=im;a[i].d=std::round(log2(im.count()));}out<<"]}";out.flush();}out<<"]}\n";}

